      "type": "string",
      "minLength": 5,
      "maxLength": 15,
      "pattern": "^[a-z0-9_-]+$",
      "description": "Desired broker ID"
    },
    "makerFee": {
      "type": "number",
      "minimum": -0.5,
      "maximum": 15,
      "description": "Maker fee in basis points (-0.5 to 15), in 0.1 bps increments. Negative values indicate rebates."
    },
    "takerFee": {
      "type": "number",
      "minimum": 1,
      "maximum": 15,
      "description": "Taker fee in basis points (1-15), in 0.1 bps increments"
    },
    "rwaMakerFee": {
      "type": "number",
      "minimum": -0.5,
      "maximum": 15,
      "description": "RWA maker fee in basis points (-0.5 to 15), in 0.1 bps increments. Negative values indicate rebates."
    },
    "rwaTakerFee": {
      "type": "number",
      "minimum": 1,
      "maximum": 15,
      "description": "RWA taker fee in basis points (1-15), in 0.1 bps increments"
    },
    "paymentType": {
      "type": "string",
      "enum": [
        "usdc",
        "order",
        "usdt"
      ],
      "default": "order",
      "description": "Payment token type"
    }
  },
  "required": [
    "txHash",
    "chain",
    "brokerId",
    "makerFee",
    "takerFee",
    "rwaMakerFee",
    "rwaTakerFee"
  ]
}

