requestBody.schema:
{
  "type": "object",
  "properties": {
    "name": {
      "type": "string",
      "minLength": 1,
      "maxLength": 120
    },
    "email": {
      "type": "string",
      "maxLength": 255,
      "format": "email"
    },
    "telegram": {
      "type": "string",
      "pattern": "^@?[a-zA-Z0-9_]{4,32}$"
    },
    "source": {
      "type": "string",
      "maxLength": 80,
      "pattern": "^[a-zA-Z0-9_-]+$",
      "default": "bd_funnel_v1"
    },
    "submitted_at": {
      "type": "string",
      "format": "date-time"
    },
    "reason": {
      "type": "string",
      "minLength": 1,
      "maxLength": 3000
    },
    "location": {
      "type": "string",
      "enum": [
        "North America",
        "Latin America",
        "Europe",
        "UK",
        "Middle East & North Africa",
        "Sub-Saharan Africa",
        "South Asia (India / Pakistan / Bangladesh)",
        "Southeast Asia",
        "East Asia (China / Korea / Japan)",
        "Oceania",
        "Other"
      ]
    },
    "channels": {
      "type": "array",
      "items": {
        "type": "string",
        "enum": [
          "x",
          "telegram",
          "youtube",
          "discord",
          "tiktok",
          "newsletter",
          "podcast",
          "irl"
        ]
      },
      "minItems": 1,
      "maxItems": 8
    },
    "links": {
      "type": "string",
      "minLength": 0,
      "maxLength": 3000,
      "default": ""
    },
    "idempotencyKey": {
      "type": "string",
      "format": "uuid"
    },
    "turnstileToken": {
      "type": "string",
      "minLength": 1,
      "maxLength": 4096
    }
  },
  "required": [
    "name",
    "email",
    "telegram",
    "reason",
    "location",
    "channels",
    "idempotencyKey"
  ]
}

